// Case Data Merger (Refactored)
// This node merges outputs from the two AI processing branches into a unified case file.
// It now expects a single input from Module 2 containing both branches.

// Get the single input item which contains the merged data from Module 2
const item = $input.first();

let parsedItems = [];
try {
  // Module 2 now sends a single item with a body.data string containing the array of results
  const unparsedData = item.json.body.data; 
  parsedItems = JSON.parse(unparsedData).map(d => ({ json: d }));
} catch (e) {
  console.error('Error parsing item data:', e, 'Received item:', JSON.stringify(item));
  return { json: { error: 'Failed to parse incoming data from Module 2.' } };
}

// Default values for the merged data
let intakeFormData = { status: 'not_processed', data: null };
let caseDocumentsAnalysis = { status: 'not_processed', data: null };
let caseId = `CASE-${new Date().getTime()}`;
let caseInfo = {};
let errors = [];

// Identify which input comes from which branch based on 'documentType'
const intakeBranch = parsedItems.find(item => item.json.documentType === 'intakeForm');
const caseDocsBranch = parsedItems.find(item => item.json.documentType === 'caseDocument');

// Process Intake Form branch
if (intakeBranch) {
    intakeFormData.status = 'processed';
    intakeFormData.data = intakeBranch.json.parsedData;
    caseInfo = intakeBranch.json.structuredData?.caseInfo || {};
    caseId = caseInfo.caseReference || caseId;
} else {
  errors.push('Intake form data branch not found.');
}

// Process Case Documents Analysis branch
if (caseDocsBranch) {
    caseDocumentsAnalysis.status = 'processed';
    caseDocumentsAnalysis.data = caseDocsBranch.json.parsedData;
    // Ensure caseInfo is consistent if intake branch was missing
    if (!caseInfo.caseReference) {
        caseInfo = caseDocsBranch.json.structuredData?.caseInfo || {};
        caseId = caseInfo.caseReference || caseId;
    }
} else {
  errors.push('Case documents analysis branch not found.');
}

// Determine overall status
let status = 'failed';
const successfulBranches = (intakeFormData.status === 'processed' ? 1 : 0) + (caseDocumentsAnalysis.status === 'processed' ? 1 : 0);

if (successfulBranches === 2) {
  status = 'completed';
} else if (successfulBranches === 1) {
  status = 'partial_success';
}

// Final unified case file
const unifiedCaseFile = {
  caseId: caseId,
  createdAt: new Date().toISOString(),
  status: status,
  caseInfo: caseInfo,
  intakeFormData: intakeFormData,
  caseDocumentsAnalysis: caseDocumentsAnalysis,
  processingSummary: {
    totalBranchesProcessed: parsedItems.length,
    successfulBranches: successfulBranches,
    failedBranches: parsedItems.length - successfulBranches,
    errors: errors
  }
};

// Construct the final output object for the next node
const result = {
  isValid: errors.length === 0,
  errors: errors,
  unifiedCaseFile: unifiedCaseFile,
  processingTimestamp: new Date().toISOString(),
  mergeMetadata: {
    nodeType: "case-data-merger",
    sourceBranches: parsedItems.length,
    detectedIntakeBranch: !!intakeBranch,
    detectedCaseDocsBranch: !!caseDocsBranch
  }
};

return [{ json: result }];

// Merge Validator Node
// This node validates the merged case data structure and adds final validation metadata
// Ensures the unified case file meets all quality requirements

// Get the input data from the Case Data Merger node
const inputData = $input.first().json;

// Initialize validation result
const validationResult = {
  isValid: true,
  errors: [],
  validatedUnifiedCaseFile: null,
  processingTimestamp: new Date().toISOString(),
  validationMetadata: {
    nodeType: "merge-validator",
    validationLevel: "final",
    validationRules: [
      "unified_structure_check",
      "required_fields_validation",
      "data_integrity_check",
      "processing_status_validation"
    ],
    validationStatus: "processing"
  }
};

// Validate that we received valid merge data
if (!inputData || !inputData.isValid) {
  validationResult.isValid = false;
  validationResult.errors.push("Invalid input: Previous merge step failed");
  if (inputData && inputData.errors) {
    validationResult.errors = validationResult.errors.concat(inputData.errors);
  }
  return [{ json: validationResult }];
}

// Extract the unified case file
const unifiedCaseFile = inputData.unifiedCaseFile;
if (!unifiedCaseFile) {
  validationResult.isValid = false;
  validationResult.errors.push("No unified case file found in merge result");
  return [{ json: validationResult }];
}

// Validation Rule 1: Unified Structure Check
const requiredTopLevelFields = ['caseId', 'createdAt', 'status', 'caseInfo', 'intakeFormData', 'caseDocumentsAnalysis', 'processingSummary'];
const missingFields = [];

for (const field of requiredTopLevelFields) {
  if (!unifiedCaseFile.hasOwnProperty(field)) {
    missingFields.push(field);
  }
}

if (missingFields.length > 0) {
  validationResult.isValid = false;
  validationResult.errors.push(`Missing required top-level fields: ${missingFields.join(', ')}`);
}

// Validation Rule 2: Required Fields Validation
if (!unifiedCaseFile.caseId || typeof unifiedCaseFile.caseId !== 'string') {
  validationResult.isValid = false;
  validationResult.errors.push("caseId must be a non-empty string");
}

if (!unifiedCaseFile.createdAt || typeof unifiedCaseFile.createdAt !== 'string') {
  validationResult.isValid = false;
  validationResult.errors.push("createdAt must be a valid timestamp string");
}

if (!unifiedCaseFile.status || !['completed', 'partial_success', 'failed'].includes(unifiedCaseFile.status)) {
  validationResult.isValid = false;
  validationResult.errors.push("status must be one of: completed, partial_success, failed");
}

// Validation Rule 3: Data Integrity Check
if (!unifiedCaseFile.processingSummary || typeof unifiedCaseFile.processingSummary !== 'object') {
  validationResult.isValid = false;
  validationResult.errors.push("processingSummary must be an object");
} else {
  const summary = unifiedCaseFile.processingSummary;

  if (typeof summary.totalBranchesProcessed !== 'number' || summary.totalBranchesProcessed < 0) {
    validationResult.isValid = false;
    validationResult.errors.push("processingSummary.totalBranchesProcessed must be a non-negative number");
  }

  if (typeof summary.successfulBranches !== 'number' || summary.successfulBranches < 0) {
    validationResult.isValid = false;
    validationResult.errors.push("processingSummary.successfulBranches must be a non-negative number");
  }

  if (typeof summary.failedBranches !== 'number' || summary.failedBranches < 0) {
    validationResult.isValid = false;
    validationResult.errors.push("processingSummary.failedBranches must be a non-negative number");
  }

  // Validate that the sum matches total
  if (summary.successfulBranches + summary.failedBranches !== summary.totalBranchesProcessed) {
    validationResult.isValid = false;
    validationResult.errors.push("processingSummary branch counts do not add up correctly");
  }
}

// Validation Rule 4: Processing Status Validation
if (!unifiedCaseFile.intakeFormData || typeof unifiedCaseFile.intakeFormData !== 'object') {
  validationResult.isValid = false;
  validationResult.errors.push("intakeFormData must be an object");
} else {
  const intakeStatus = unifiedCaseFile.intakeFormData.status;
  if (!['processed', 'failed', 'not_processed'].includes(intakeStatus)) {
    validationResult.isValid = false;
    validationResult.errors.push("intakeFormData.status must be one of: processed, failed, not_processed");
  }
}

if (!unifiedCaseFile.caseDocumentsAnalysis || typeof unifiedCaseFile.caseDocumentsAnalysis !== 'object') {
  validationResult.isValid = false;
  validationResult.errors.push("caseDocumentsAnalysis must be an object");
} else {
  const caseDocsStatus = unifiedCaseFile.caseDocumentsAnalysis.status;
  if (!['processed', 'failed', 'not_processed'].includes(caseDocsStatus)) {
    validationResult.isValid = false;
    validationResult.errors.push("caseDocumentsAnalysis.status must be one of: processed, failed, not_processed");
  }
}

// If validation passes, add final validation metadata
if (validationResult.errors.length === 0) {
  const finalValidatedCaseFile = {
    ...unifiedCaseFile,
    finalValidation: {
      validatedAt: new Date().toISOString(),
      validationLevel: "final",
      validationStatus: "passed",
      validatorVersion: "1.0.0",
      originalMergeTimestamp: inputData.processingTimestamp,
      mergeMetadata: inputData.mergeMetadata || {}
    }
  };

  validationResult.validatedUnifiedCaseFile = finalValidatedCaseFile;
  validationResult.validationMetadata.validationStatus = "completed";
  validationResult.message = "Unified case file successfully validated and finalized";
} else {
  validationResult.isValid = false;
  validationResult.validationMetadata.validationStatus = "failed";
}

// Preserve original merge data for reference
validationResult.originalMergeData = {
  mergeResult: inputdata,
  mergeTimestamp: inputData.processingTimestamp
};

// Return the validation result
return [{ json: validationResult }];

// Generate debug package with workflow data for UI visibility
const debugPackage = {
  timestamp: new Date().toISOString(),
  workflow: '3_merging',
  inputItemCount: $input.all().length,
  nodeExecutionData: $input.all(),
  executionInfo: {
    nodeId: 'Generate & Send Debug Package',
    processingTime: new Date().toISOString(),
    dataTypes: $input.all().map(item => ({
      hasJson: !!item.json,
      hasBinary: !!item.binary,
      jsonKeys: item.json ? Object.keys(item.json) : [],
      binaryKeys: item.binary ? Object.keys(item.binary) : []
    }))
  }
};

// Return both debug output (visible in Node Output → JSON) and pass-through data
return [
  // First output: Debug data (visible in UI)
  { 
    json: { 
      debug: debugPackage,
      message: 'Debug package generated - check Node Output → JSON tab'
    } 
  },
  // Remaining outputs: Pass through original data for workflow continuation
  ...$input.all()
];
